// ============================================================
// HEALTH CHECK: Compile Report (v3.0)
// ============================================================

const dbCheck = $('Check Database Connection').first().json;
const sessionStats = $('Get Session Statistics').first().json;
const approvedStats = $('Get Approved Statistics').first().json;
const errorStats = $('Get Error Statistics').first().json;

const timestamp = new Date().toISOString();

// Determine overall health
let overallStatus = '🟢 HEALTHY';
let issues = [];

// Check for issues
if (!dbCheck || dbCheck.status !== 'OK') {
  overallStatus = '🔴 CRITICAL';
  issues.push('Database connection failed');
}

const errorsLastHour = parseInt(errorStats?.errors_last_hour) || 0;
if (errorsLastHour > 10) {
  overallStatus = '🟡 WARNING';
  issues.push(`High error rate: ${errorsLastHour} errors/hour`);
}

if (errorsLastHour > 50) {
  overallStatus = '🔴 CRITICAL';
}

// Compile report
const report = {
  timestamp: timestamp,
  overall_status: overallStatus,
  issues: issues,
  metrics: {
    database: dbCheck?.status || 'UNKNOWN',
    total_sessions: sessionStats?.total_sessions || 0,
    active_sessions: sessionStats?.active_sessions || 0,
    completed_sessions: sessionStats?.completed_sessions || 0,
    sessions_today: sessionStats?.sessions_today || 0,
    sessions_last_hour: sessionStats?.sessions_last_hour || 0,
    total_approved: approvedStats?.total_approved || 0,
    approved_today: approvedStats?.approved_today || 0,
    errors_last_hour: errorsLastHour
  }
};

// Format Telegram message
const telegramMessage = 
  `📊 <b>HR Bot Health Check</b>\n\n` +
  `Status: ${overallStatus}\n\n` +
  `<b>📈 Sessions:</b>\n` +
  `• Total: ${report.metrics.total_sessions}\n` +
  `• Active: ${report.metrics.active_sessions}\n` +
  `• Today: ${report.metrics.sessions_today}\n` +
  `• Last hour: ${report.metrics.sessions_last_hour}\n\n` +
  `<b>✅ Approved:</b>\n` +
  `• Total: ${report.metrics.total_approved}\n` +
  `• Today: ${report.metrics.approved_today}\n\n` +
  `<b>❌ Errors:</b>\n` +
  `• Last hour: ${report.metrics.errors_last_hour}\n\n` +
  `🕐 ${timestamp}`;

return {
  ...report,
  telegram_message: telegramMessage,
  should_notify: overallStatus !== '🟢 HEALTHY' || (new Date().getHours() === 9 && new Date().getMinutes() < 30)
};

// Log health check (no notification needed)
console.log('✅ Health check completed:', $json.overall_status);
return $json;
